"""Generate src/cli/goldens.rs: command lines run through the reference
AWS CLI (ref_harness.py) with their exit code, stdout, stderr, and the
parameters handed to the client.

    PYTHONPATH=$AWSR_REFERENCE_SRC python3 src/cli/testdata/gen_cli_goldens.py \
        src/cli/testdata/cli_cases.txt > src/cli/goldens.rs

Each line of the case file is a shell-quoted command line, optionally
prefixed with `ENV=value` assignments for the AWS CLI configuration
(`AWS_CLI_ERROR_FORMAT`, ...). `@DIR@` stands for a directory holding the
fixtures of FIXTURES.
"""

import json
import os
import shlex
import subprocess
import sys
import tempfile

HERE = os.path.dirname(os.path.abspath(__file__))

FIXTURES = {
    'filters.json': b'[{"Name": "a", "Values": ["b", "c"]}]',
    'item.json': b'{"k": {"S": "v"}}',
    'input.json': b'{"TableName": "t", "Item": {"k": {"S": "v"}}}',
    'input.yaml': b'TableName: t\nItem:\n  k:\n    S: v\n',
    'crlf.txt': b'line1\r\nline2\r\n',
    'latin1.txt': b'caf\xe9',
    'body.bin': b'\x00\x01\x02binary',
    'policy.json': b'{"Version": "2012-10-17", "Statement": []}',
    'list.json': b'["a", "b"]',
}


def rs(s):
    out = ['"']
    for c in s:
        if c == '\\':
            out.append('\\\\')
        elif c == '"':
            out.append('\\"')
        elif c == '\n':
            out.append('\\n')
        elif c == '\r':
            out.append('\\r')
        elif c == '\t':
            out.append('\\t')
        elif ord(c) < 0x20 or ord(c) == 0x7f:
            out.append('\\u{%x}' % ord(c))
        else:
            out.append(c)
    out.append('"')
    return ''.join(out)


def main():
    cases = []
    with open(sys.argv[1]) as f:
        for line in f:
            line = line.rstrip('\n')
            if line.strip() and not line.startswith('#'):
                cases.append(line)
    tmp = tempfile.mkdtemp(prefix='awsr-goldens-')
    fixture_dir = os.path.join(tmp, 'fx')
    os.mkdir(fixture_dir)
    home = os.path.join(tmp, 'home')
    os.mkdir(home)
    for name, data in FIXTURES.items():
        with open(os.path.join(fixture_dir, name), 'wb') as f:
            f.write(data)
    base_env = {
        'PATH': os.environ['PATH'],
        'PYTHONPATH': os.environ['PYTHONPATH'],
        'HOME': home,
        'AWS_CONFIG_FILE': os.path.join(home, 'config'),
        'AWS_SHARED_CREDENTIALS_FILE': os.path.join(home, 'credentials'),
        'AWS_REGION': 'us-east-1',
        'AWS_ACCESS_KEY_ID': 'AKIDEXAMPLE',
        'AWS_SECRET_ACCESS_KEY': 'secret',
        'AWS_EC2_METADATA_DISABLED': 'true',
        'LC_ALL': 'C.UTF-8',
    }
    out = []
    w = out.append
    w('//! Generated by `src/cli/testdata/gen_cli_goldens.py` from')
    w('//! `src/cli/testdata/cli_cases.txt` and the reference AWS CLI. Do not')
    w('//! edit.')
    w('')
    w('use super::golden_tests::Golden;')
    w('')
    w('pub(super) const FIXTURES: &[(&str, &[u8])] = &[')
    for name, data in FIXTURES.items():
        w(f'    ({rs(name)}, &{list(data)}),')
    w('];')
    w('')
    w('pub(super) const GOLDENS: &[Golden] = &[')
    for case in cases:
        words = shlex.split(case.replace('@DIR@', fixture_dir))
        env = dict(base_env)
        case_env = []
        while words and '=' in words[0] and words[0].split('=', 1)[0].isupper():
            k, v = words.pop(0).split('=', 1)
            env[k] = v
            case_env.append((k, v))
        p = subprocess.run(
            [sys.executable, os.path.join(HERE, 'ref_harness.py')] + words,
            capture_output=True, env=env, cwd=tmp,
        )
        stdout = p.stdout.decode()
        stderr_lines = []
        record = None
        for line in p.stderr.decode().splitlines(keepends=True):
            if line.startswith('@@'):
                record = line[2:].rstrip('\n')
            else:
                stderr_lines.append(line)
        stderr = ''.join(stderr_lines)
        if record is not None:
            stdout = ''
        fix = lambda s: s.replace(fixture_dir, '@DIR@').replace(
            'usage: ref_harness.py ', 'usage: awsr '
        )
        argv = [fix(x) for x in words]
        w('    Golden {')
        w(f'        args: &[{", ".join(rs(a) for a in argv)}],')
        w(f'        env: &[{", ".join(f"({rs(k)}, {rs(v)})" for k, v in case_env)}],')
        w(f'        rc: {p.returncode},')
        w(f'        stdout: {rs(fix(stdout))},')
        w(f'        stderr: {rs(fix(stderr))},')
        if record is None:
            w('        record: None,')
        else:
            w(f'        record: Some({rs(fix(record))}),')
        w('    },')
    w('];')
    print('\n'.join(out))


if __name__ == '__main__':
    main()
